<script setup>
import { locationDescription } from '../services/locations.js'
defineProps({location:Object,offline:Boolean})
</script>
<template><div class="location-summary"><h3>Last known location</h3><p><strong>{{offline?'OFFLINE — location is not current':location?.status??'UNAVAILABLE'}}</strong> · {{location?.reason??'Location Unavailable — no positioning observation received'}}</p><template v-if="location?.lastKnown"><p>{{locationDescription(location.lastKnown)}}</p><p><span class="badge">{{location.lastKnown.simulation?'SIMULATED':location.lastKnown.source}}</span> · {{location.lastKnown.source==='BLE'?'Zone/checkpoint proximity only':location.lastKnown.coordinateFrame||'Zone observation'}}</p><p>Observed {{new Date(location.lastKnown.timestamp).toLocaleString()}} · Received {{new Date(location.lastKnown.receivedAt).toLocaleString()}}</p><p>Device {{location.lastKnown.deviceId}} · Accuracy {{location.lastKnown.accuracyMeters==null?'not reported':`${location.lastKnown.accuracyMeters} m`}} · Confidence {{location.lastKnown.confidence==null?'not reported':`${Math.round(location.lastKnown.confidence*100)}% (device-reported)`}}</p><p v-if="location.lastKnown.simulation">Fictional movement. This is not a physical worker position.</p></template></div></template>
